import React from "react";
import NavBar from "../../Components/NavBar/NavBar";
import MainHeading from "../../Components/Headings/MainHeading";

function About() {
  return (
    <div className=" text-white">
      <NavBar page={"About"} />
      <div className="  text-center p-10">
        <MainHeading text={"About Solar Explore"} />
        <p>
          Welcome to Solar Explore, your trusted partner in discovering,
          learning about, and adopting solar energy solutions. We are dedicated
          to creating a sustainable future by helping individuals, businesses,
          and communities unlock the vast potential of solar power.
        </p>
        <MainHeading text={"Who We Are"} />
        <p>
          At Solar Explore, we are passionate about renewable energy and the
          environment. Our team of experts, engineers, and advocates is
          committed to simplifying the transition to solar energy by providing
          accurate information, cutting-edge tools, and personalized solutions
          tailored to your needs.
        </p>
        <MainHeading text={"What We Do"} />
      </div>
    </div>
  );
}

export default About;
